/* Resolve real Google Place photos on demand; never persist expiring photo URLs. */
const RTPhotos=(()=>{
 const cache=new Map();let observer=null,active=0,queue=[],blocked=false;
 const norm=s=>s.toLowerCase().replace(/[^a-z0-9 ]/g,' ').split(/\s+/).filter(x=>x.length>2&&!['the','inc','club','school','primary','college','community','centre','center','group','australia','melbourne'].includes(x));
 async function find(e){if(cache.has(e.id))return cache.get(e.id);const job=(async()=>{if(blocked)return {photos:[],error:'Google photo lookup is unavailable. Website photos are shown where collected.'};try{await RTMaps.load();const {Place}=await google.maps.importLibrary('places');const request={textQuery:e.name+' '+e.address,fields:['id','displayName','location','photos','googleMapsURI'],maxResultCount:3,region:'au'};if(e.lat!=null&&e.lon!=null)request.locationBias={center:{lat:e.lat,lng:e.lon},radius:600};const {places}=await Place.searchByText(request);const words=norm(e.name);const p=places.find(p=>{if(!p.location||e.lat==null||e.lon==null)return false;const delta=Math.hypot((p.location.lat()-e.lat)*111,(p.location.lng()-e.lon)*88);const matched=words.filter(w=>norm(p.displayName).includes(w)).length;return delta<.4&&words.length>0&&matched/words.length>=.7});if(!p)return {photos:[],error:'No photo listing could be confidently matched to this name and address.'};if(!p.photos?.length)await p.fetchFields({fields:['photos']});return {photos:(p.photos||[]).slice(0,6).map(x=>({url:x.getURI({maxWidth:900}),caption:p.displayName+' · Google Maps photo',source_url:p.googleMapsURI,authors:(x.authorAttributions||[]).map(a=>({name:a.displayName,url:a.uri})),kind:'google'})),error:'No public photos returned for the matched listing.'}}catch(e){blocked=true;return {photos:[],error:'Google photo search is unavailable. Places API (New) must be enabled for the map key; existing website photos remain available.'}}})();cache.set(e.id,job);return job}
 function markup(result,large){if(!result.photos.length)return `<div class="photo-missing"><small>${esc(result.error)}</small></div>`;return `<div class="${large?'photo-gallery':'photo-thumb'}">${result.photos.slice(0,large?6:1).map(p=>`<figure><img loading="lazy" src="${esc(p.url)}" alt="${esc(p.caption)}"><figcaption><span>Google Maps</span> · ${p.authors.map(a=>a.url?anchor(a.url,a.name):esc(a.name)).join(', ')||'Photo contributor'} ${p.source_url?anchor(p.source_url,'Place source'):''}</figcaption></figure>`).join('')}</div>`}
 function pump(){while(active<2&&queue.length){const {node,e}=queue.shift();if(!node.isConnected)continue;active++;find(e).then(r=>{if(node.isConnected){node.innerHTML=markup(r,node.dataset.large==='true');node.querySelectorAll('img').forEach(img=>img.onerror=()=>{img.alt='Photo currently unavailable';img.style.display='none'})}}).finally(()=>{active--;pump()})}}
 function bind(rows){if(observer)observer.disconnect();queue=[];observer=new IntersectionObserver(entries=>{for(const x of entries)if(x.isIntersecting){observer.unobserve(x.target);const e=rows.find(e=>e.id===x.target.dataset.photo);if(e){queue.push({node:x.target,e});pump()}}},{rootMargin:'100px'});document.querySelectorAll('[data-photo]').forEach(n=>observer.observe(n))}
 return {bind};
})();
